const $=s=>document.querySelector(s);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b0+(\d+)/g,'$1');
const bookmarkIcon='<svg viewBox="0 0 20 24" aria-hidden="true"><path d="M4 3h12v18l-6-4-6 4z"/></svg>';
const documentIcon='<svg viewBox="0 0 24 28" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M5 2h10l5 5v19H5z"/><path d="M15 2v6h5M8 13h9M8 17h9M8 21h6"/></svg>';
let catalog,records=[],index=new Map(),saved=new Set(),filtered=[],memoryOnly=false;
let state={view:'explorar',q:'',topic:'todos',type:'',year:'',page:1};
const pageSize=8;
try{const value=JSON.parse(localStorage.getItem('aduana-abierta-library')||'[]');if(Array.isArray(value))saved=new Set(value.filter(x=>typeof x==='string'));}catch{memoryOnly=true;}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function readHash(){const [view,qs='']=location.hash.slice(1).split('?');const p=new URLSearchParams(qs);state={view:['explorar','importar','exportar','normativa','servicios','guardados','fuentes'].includes(view)?view:'explorar',q:p.get('q')||'',topic:p.get('tema')||'todos',type:p.get('tipo')||'',year:p.get('ano')||'',page:1};}
function saveHash(){const p=new URLSearchParams();if(state.q)p.set('q',state.q);if(state.topic!=='todos')p.set('tema',state.topic);if(state.type)p.set('tipo',state.type);if(state.year)p.set('ano',state.year);history.replaceState(null,'','#'+state.view+(p.size?'?'+p:''));}
function goSearch(q){state={...state,view:'explorar',q,topic:'todos',type:'',year:'',page:1};saveHash();renderView();$('#query').focus();}
function toggleSaved(id){if(!index.has(id))return;if(saved.has(id))saved.delete(id);else saved.add(id);try{localStorage.setItem('aduana-abierta-library',JSON.stringify([...saved]));}catch{memoryOnly=true;}notify(memoryOnly?'Guardado durante esta sesión. El navegador no permite conservarlo.':saved.has(id)?'Recurso guardado en Mi biblioteca.':'Recurso retirado de Mi biblioteca.');updateSaved();renderResults();if($('#resource-dialog').open)renderDialog(id);}
function updateSaved(){saved=new Set([...saved].filter(id=>index.has(id)));$('#saved-count').textContent=saved.size;}
function resourceCard(r){const description=r.description.length>160?r.description.slice(0,157).trimEnd()+'…':r.description;return `<article class="resource"><div class="doc-icon">${documentIcon}</div><div><div class="resource-meta"><span>${safe(r.subtype)}</span><span class="divider"></span><span>${safe(r.year||r.format)}</span></div><button class="resource-title" data-detail="${r.id}">${safe(r.title)}</button>${description?`<p>${safe(description)}</p>`:''}<div class="resource-links"><button data-detail="${r.id}">Ver ficha</button><a href="${safe(r.url)}" target="_blank" rel="noopener noreferrer">Fuente oficial <span aria-hidden="true">↗</span><span class="sr-only"> de ${safe(r.title)}, abre otra pestaña</span></a></div></div><button class="bookmark" data-save="${r.id}" aria-label="${saved.has(r.id)?'Retirar de mi biblioteca':'Guardar'}: ${safe(r.title)}" aria-pressed="${saved.has(r.id)}">${bookmarkIcon}</button></article>`;}
function baseRecords(){if(state.view==='guardados')return records.filter(r=>saved.has(r.id));if(state.view==='normativa')return records.filter(r=>r.legal||r.tags.includes('normativa'));if(state.view==='servicios')return records.filter(r=>r.tags.includes('servicios'));if(state.view==='importar')return records.filter(r=>r.tags.includes('importacion'));if(state.view==='exportar')return records.filter(r=>r.tags.includes('exportacion'));return records;}
function renderCategories(){const base=baseRecords();$('#categories').innerHTML=catalog.categories.map(c=>{let n=c.id==='todos'?base.length:base.filter(r=>r.tags.includes(c.id)).length;return `<button class="topic ${state.topic===c.id?'active':''}" data-topic="${c.id}" aria-pressed="${state.topic===c.id}"><span>${safe(c.label)}</span><span>${n.toLocaleString('es-CO')}</span></button>`;}).join('');}
function renderResults(){const terms=normalize(state.q).split(/\s+/).filter(t=>t&&!['de','del','la','el','las','los','un','una','y','en'].includes(t));filtered=baseRecords().filter(r=>(state.topic==='todos'||r.tags.includes(state.topic))&&(!state.type||r.type===state.type||r.subtype===state.type)&&(!state.year||String(r.year)===state.year)&&terms.every(t=>/^\d+$/.test(t)?new RegExp('\\b'+t+'\\b').test(r.search):r.search.includes(t)));
 if(terms.length){filtered=filtered.map(r=>({r,score:terms.reduce((n,t)=>n+(r.titleKey.includes(t)?15:0),0)+r.featured/30})).sort((a,b)=>b.score-a.score).map(x=>x.r);}
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize));state.page=Math.min(state.page,pages);$('#result-count').textContent=filtered.length.toLocaleString('es-CO')+' recursos';
 $('#results-title').textContent=state.q?`Resultados para «${state.q}»`:state.topic!=='todos'?catalog.categories.find(c=>c.id===state.topic)?.label||'Recursos de consulta':({explorar:'Lo esencial, bien organizado.',normativa:'Normas y criterios, por tema.',guardados:'Tus recursos de consulta.',servicios:'Accede al servicio correcto.',importar:'Recursos para importar.',exportar:'Recursos para exportar.'}[state.view]||'Recursos de consulta');
 $('#clear-filters').hidden=!state.q&&state.topic==='todos'&&!state.type&&!state.year;
 if(!filtered.length){$('#results').innerHTML=state.view==='guardados'&&!saved.size?`<div class="empty"><h3>Tu biblioteca empieza aquí.</h3><p>Guarda una norma, una guía o un trámite con el icono de marcador. Permanecerá disponible en este navegador.</p><a href="#explorar">Explorar recursos</a></div>`:`<div class="empty"><h3>No encontramos coincidencias.</h3><p>Prueba con el número de la norma o con un tema más general. Puedes ampliar la búsqueda al texto completo en la DIAN.</p><a href="https://normograma.dian.gov.co/dian/compilacion/herramientas_busqueda.html" target="_blank" rel="noopener noreferrer">Abrir el buscador oficial ↗</a></div>`;}else{$('#results').innerHTML=filtered.slice((state.page-1)*pageSize,state.page*pageSize).map(resourceCard).join('');}
 $('#results').setAttribute('aria-busy','false');$('#page-count').textContent=`Página ${state.page} de ${pages.toLocaleString('es-CO')}`;$('#previous').disabled=state.page===1;$('#next').disabled=state.page===pages;$('.pagination').hidden=filtered.length===0;
}
const routes={
 importar:[['Conoce tu mercancía','La consulta comienza con la descripción técnica, la composición y el uso del producto. Revisa su clasificación y la información que presenta el arancel.','arancel'],['Revisa la modalidad y sus condiciones','Consulta las modalidades de importación y ubica la normativa aplicable a tu operación. En la fuente oficial puedes revisar los cambios y las notas de vigencia.','norma1165'],['Comprueba origen y valoración','Revisa las reglas de origen del acuerdo comercial que corresponda y los criterios de valoración aduanera. El país de envío y el origen de una mercancía no son necesariamente lo mismo.','origen','valoracion'],['Prepara la declaración','Consulta el instructivo de importaciones y revisa si la declaración anticipada resulta aplicable. Contrasta los datos con los documentos de tu operación.','importacion','anticipada'],['Ubica el servicio y la orientación','Accede a los servicios aduaneros oficiales. Si se presenta una contingencia, revisa las instrucciones publicadas por la DIAN.','servicios','contingencia']],
 exportar:[['Define la operación y el producto','Ubica la subpartida y consulta el Abecé de exportación. Identifica la modalidad y revisa las condiciones de salida de la mercancía.','exportacion','arancel'],['Consulta las reglas de origen','Cuando tu operación utilice una preferencia arancelaria, consulta el acuerdo correspondiente y la prueba de origen que establece.','origen'],['Revisa el procedimiento aduanero','Consulta la regulación de exportaciones, sus modificaciones y la reglamentación operativa en la compilación oficial.','norma1165','res46'],['Accede a los servicios de exportación','Ubica el servicio oficial de operaciones integradas de exportación y los servicios de origen desde la página transaccional de la DIAN.','servicios'],['Conserva tus referencias de consulta','Guarda los documentos que utilizas y revisa la publicación de novedades. Puedes complementar la consulta con las estadísticas oficiales.','novedades','estadisticas']]
};
function renderRoute(){const steps=routes[state.view];$('#route-panel').hidden=!steps;if(!steps)return;$('#route-panel').innerHTML=`<div class="route-layout"><div><p class="route-label">Ruta de consulta · 5 momentos para orientar tu revisión</p>${steps.map((step,i)=>`<details class="step" ${i===0?'open':''}><summary><span class="step-number">0${i+1}</span>${safe(step[0])}</summary><div class="step-content"><p>${safe(step[1])}</p>${step.slice(2).map(id=>index.get(id)).filter(Boolean).map(r=>`<button class="primary" data-detail="${r.id}">${safe(r.title)} <span aria-hidden="true">↗</span></button>`).join(' ')}</div></details>`).join('')}</div><aside class="route-note"><p class="eyebrow">PARA TU OPERACIÓN</p><h3>Una ruta para consultar.</h3><p>Los requisitos dependen de la mercancía, la modalidad y las condiciones de cada operación. Esta guía organiza tus consultas; los trámites se realizan ante las entidades competentes.</p><a href="https://www.dian.gov.co/aduanas/Paginas/Inicio.aspx" target="_blank" rel="noopener noreferrer">Ir al portal de Aduanas ↗</a></aside></div>`;}
function renderSources(){const count=catalog.coverage;$('#sources-panel').innerHTML=`<p class="eyebrow">PROCEDENCIA Y COBERTURA</p><h2>La fuente siempre está a la vista.</h2><p>Aduana Abierta reúne referencias públicas de la DIAN para facilitar la consulta aduanera. Cada ficha enlaza el documento original o el servicio oficial. El catálogo se preparó el <strong>${formatDate(catalog.updated)}</strong>.</p><div class="coverage"><div><strong>${count.resources.toLocaleString('es-CO')}</strong><span>recursos catalogados</span></div><div><strong>${count.legal.toLocaleString('es-CO')}</strong><span>referencias jurídicas</span></div><div><strong>${count.legalIndexes}</strong><span>índices jurídicos recorridos</span></div></div><h2>Qué puedes consultar</h2><p>Normativa, doctrina y jurisprudencia del índice aduanero; las guías y accesos del portal de Aduanas; origen, arancel, valoración, usuarios y OEA; servicios electrónicos, contingencias, regímenes especiales y estadísticas. Los títulos y las descripciones jurídicas proceden del índice oficial. Las fichas de orientación sintetizan la finalidad del recurso.</p><h2>Cómo interpretar el catálogo</h2><p>La búsqueda revisa títulos, descripciones y temas catalogados. Para buscar dentro del texto completo, utiliza el buscador del normograma. El catálogo incluye documentos históricos y no certifica su vigencia. No se sincroniza automáticamente ni constituye una copia integral de todos los archivos de la DIAN. Las modificaciones, derogatorias, decisiones judiciales y condiciones de aplicación deben revisarse en la fuente oficial.</p><div class="source-grid"><a href="https://www.dian.gov.co/aduanas/Paginas/Inicio.aspx" target="_blank" rel="noopener noreferrer">Portal de Aduanas ↗<span>Operación, técnica, facilitación y servicios</span></a><a href="https://normograma.dian.gov.co/dian/compilacion/aduanero.html?q=ADUANERO" target="_blank" rel="noopener noreferrer">Compilación jurídica aduanera ↗<span>Normativa, doctrina y jurisprudencia</span></a><a href="https://normograma.dian.gov.co/dian/compilacion/herramientas_busqueda.html" target="_blank" rel="noopener noreferrer">Búsqueda avanzada oficial ↗<span>Consulta de textos completos en la DIAN</span></a><a href="https://www.dian.gov.co/dian/cifras/Paginas/EstadisticasComEx.aspx" target="_blank" rel="noopener noreferrer">Estadísticas de comercio exterior ↗<span>Bases, tablero COMEX y series históricas</span></a></div><h2>Identidad visual y uso</h2><p>El logosímbolo de la Universidad del Valle se conserva en sus colores originales, sobre blanco y sin deformaciones. La composición utiliza Arial, fondos blancos y texto de alto contraste; el rojo institucional se reserva al título principal y al logosímbolo. Su uso en este proyecto no acredita aval institucional. Los documentos enlazados y las marcas conservan sus respectivos titulares.</p><h2>Mi biblioteca</h2><p>Los marcadores se guardan en este navegador. No necesitas una cuenta y no se envían a un servidor. Si borras los datos del navegador, se eliminan tus marcadores.</p>`;}
function formatDate(date){return new Intl.DateTimeFormat('es-CO',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));}
const headings={explorar:['INFORMACIÓN OFICIAL, A TU ALCANCE','Tu centro de consulta aduanera.','Normas, trámites y orientación de la DIAN para importar y exportar.'],importar:['RUTA DE IMPORTACIÓN','Antes de importar,<br>consulta cada paso.','Una ruta para ubicar la información oficial de tu operación.'],exportar:['RUTA DE EXPORTACIÓN','Prepara tu salida<br>al mercado internacional.','Normativa, origen y servicios para orientar tu exportación.'],normativa:['BIBLIOTECA JURÍDICA','Encuentra la norma.<br>Consulta su contexto.','Decretos, resoluciones, doctrina y jurisprudencia aduanera con acceso a la fuente oficial.'],servicios:['SERVICIOS ADUANEROS','El trámite correcto,<br>en el lugar correcto.','Accesos a los servicios electrónicos, formularios y orientación de la DIAN.'],guardados:['MI BIBLIOTECA','Lo que necesitas consultar,<br>siempre a mano.','Tus recursos guardados en este navegador.'],fuentes:['FUENTES Y ALCANCE','Consulta con contexto.<br>Decide con respaldo.','Conoce la procedencia de los recursos y el alcance de este portal.']};
function renderView(){const h=headings[state.view];$('#eyebrow').textContent=h[0];$('#page-title').innerHTML=h[1];$('#intro-copy').innerHTML=h[2];document.title=`${{explorar:'Consulta de comercio exterior',importar:'Ruta de importación',exportar:'Ruta de exportación',normativa:'Normativa aduanera',servicios:'Servicios DIAN',guardados:'Mi biblioteca',fuentes:'Fuentes y alcance'}[state.view]} | Aduana Abierta`;
 document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===state.view);if(a.dataset.view===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#query').value=state.q;$('#type-filter').value=state.type;$('#year-filter').value=state.year;$('#workspace').hidden=state.view==='fuentes';$('#sources-panel').hidden=state.view!=='fuentes';$('.search-area').hidden=state.view==='fuentes';$('.bottom-routes').hidden=['importar','exportar','fuentes'].includes(state.view);$('.edition').hidden=['fuentes','guardados'].includes(state.view);renderRoute();if(state.view==='fuentes')renderSources();else{renderCategories();renderResults();}}
function renderDialog(id){const r=index.get(id);if(!r)return;const topic=r.tags.map(t=>catalog.categories.find(c=>c.id===t)?.label).filter(Boolean).join(' · ');$('#dialog-content').innerHTML=`<p class="eyebrow">${safe(r.subtype)} · ${safe(r.format)}</p><h2 id="dialog-title">${safe(r.title)}</h2><p class="summary">${safe(r.description||'Consulta el contenido de este recurso en su fuente oficial.')}</p><dl><dt>Temas</dt><dd>${safe(topic)}</dd><dt>Fuente</dt><dd>${safe(new URL(r.url).hostname)}</dd>${r.year?`<dt>Año de referencia</dt><dd>${r.year}</dd>`:''}<dt>Catalogado el</dt><dd>${formatDate(catalog.updated)}</dd>${r.sourceIndex?`<dt>Procedencia</dt><dd><a href="${safe(r.sourceIndex)}" target="_blank" rel="noopener noreferrer">Ver índice de la fuente ↗</a></dd>`:''}</dl><p class="notice">${r.legal?'Referencia jurídica, que puede incluir antecedentes históricos. Revisa las notas de vigencia, modificaciones y decisiones judiciales antes de aplicarla.':'El contenido completo y las condiciones de uso se consultan en la fuente oficial. El catálogo no reemplaza el trámite ante la DIAN.'}</p><div class="dialog-actions"><a class="primary" href="${safe(r.url)}" target="_blank" rel="noopener noreferrer">${r.format==='PDF'?'Abrir PDF oficial':'Consultar fuente oficial'} <span aria-hidden="true">↗</span></a><button class="secondary" data-save="${r.id}">${saved.has(r.id)?'Retirar de mi biblioteca':'Guardar en mi biblioteca'}</button></div>`;}
function openDialog(id){renderDialog(id);if(index.has(id))$('#resource-dialog').showModal();}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(!catalog){notify('El catálogo todavía se está cargando.');return;}if(button.dataset.detail)openDialog(button.dataset.detail);if(button.dataset.save)toggleSaved(button.dataset.save);if(button.dataset.open)openDialog(button.dataset.open);if(button.dataset.query)goSearch(button.dataset.query);if(button.dataset.topic){state.topic=button.dataset.topic;state.page=1;saveHash();renderCategories();renderResults();}});
$('.close-dialog').addEventListener('click',()=>$('#resource-dialog').close());$('#resource-dialog').addEventListener('click',e=>{if(e.target===$('#resource-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();if(!catalog)return;state.q=$('#query').value.trim();state.page=1;saveHash();renderResults();});
let searchTimer;$('#query').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(!catalog)return;state.q=$('#query').value.trim();state.page=1;saveHash();renderResults();},180);});
for(const [selector,prop] of [['#type-filter','type'],['#year-filter','year']])$(selector).addEventListener('change',e=>{state[prop]=e.target.value;state.page=1;saveHash();renderResults();});
$('#clear-filters').addEventListener('click',()=>{state={...state,q:'',topic:'todos',type:'',year:'',page:1};saveHash();renderView();});
for(const [selector,delta] of [['#previous',-1],['#next',1]])$(selector).addEventListener('click',()=>{state.page+=delta;renderResults();$('.results-heading').scrollIntoView({behavior:'auto',block:'start'});});
window.addEventListener('hashchange',()=>{if(!catalog)return;readHash();renderView();$('#consulta').scrollIntoView({behavior:'auto',block:'start'});});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#resource-dialog').open){e.preventDefault();if(state.view==='fuentes'){state.view='explorar';saveHash();renderView();}$('#query').focus();}});
window.addEventListener('storage',e=>{if(e.key==='aduana-abierta-library'){try{const v=JSON.parse(e.newValue||'[]');if(Array.isArray(v)){saved=new Set(v.filter(x=>typeof x==='string'));updateSaved();renderResults();}}catch{}}});
async function start(){try{const response=await fetch('catalog.json');if(!response.ok)throw Error('No se pudo obtener el catálogo');catalog=await response.json();records=catalog.resources;for(const r of records){r.titleKey=normalize(r.title);r.search=normalize([r.title,r.description,r.group,r.subtype,...r.tags].join(' '));index.set(r.id,r);}updateSaved();$('#year-filter').innerHTML='<option value="">Cualquier año</option>'+[...new Set(records.map(r=>r.year).filter(Boolean))].sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('');readHash();if(!catalog.categories.some(c=>c.id===state.topic))state.topic='todos';renderView();}catch(error){$('#results').setAttribute('aria-busy','false');$('#result-count').textContent='Catálogo no disponible';$('#results').innerHTML='<div class="empty"><h3>No se pudo cargar el catálogo.</h3><p>Recarga la página o consulta la fuente oficial.</p><a href="https://www.dian.gov.co/aduanas/Paginas/Inicio.aspx" target="_blank" rel="noopener noreferrer">Ir a Aduanas DIAN ↗</a></div>';}}
start();
